"""Writes the benchmark worlds. Run once when the worlds change: python3 -m hexapod_gazebo.worlds_gen <worlds dir>."""
import math
import pathlib
import random
import sys

HEADER = '''<?xml version="1.0"?>
<!-- Generated by hexapod_gazebo/worlds_gen.py -->
<sdf version="1.9">
<world name="{name}">
  <physics type="dart"><max_step_size>0.001</max_step_size><real_time_factor>1.0</real_time_factor></physics>
  <plugin filename="gz-sim-physics-system" name="gz::sim::systems::Physics"/>
  <plugin filename="gz-sim-contact-system" name="gz::sim::systems::Contact"/>
  <plugin filename="gz-sim-imu-system" name="gz::sim::systems::Imu"/>
  <plugin filename="gz-sim-sensors-system" name="gz::sim::systems::Sensors"><render_engine>ogre2</render_engine></plugin>
  <plugin filename="gz-sim-scene-broadcaster-system" name="gz::sim::systems::SceneBroadcaster"/>
  <plugin filename="gz-sim-user-commands-system" name="gz::sim::systems::UserCommands"/>
  <gravity>0 0 -9.80665</gravity>
  <scene><ambient>0.6 0.6 0.6 1</ambient><background>0.8 0.85 0.9 1</background><grid>false</grid></scene>
  <light type="directional" name="sun"><cast_shadows>true</cast_shadows><pose>0 0 10 0 0 0</pose><diffuse>0.9 0.9 0.9 1</diffuse><specular>0.2 0.2 0.2 1</specular><direction>-0.5 0.2 -1</direction></light>
'''
FOOTER = '</world>\n</sdf>\n'


def ground(mu=1.0, name='ground', pose='0 0 0 0 0 0'):
    return f'''  <model name="{name}"><static>true</static><pose>{pose}</pose><link name="link">
    <collision name="collision"><geometry><plane><normal>0 0 1</normal><size>40 40</size></plane></geometry>
      <surface><friction><ode><mu>{mu}</mu><mu2>{mu}</mu2></ode></friction></surface></collision>
    <visual name="visual"><geometry><plane><normal>0 0 1</normal><size>40 40</size></plane></geometry>
      <material><ambient>0.72 0.74 0.76 1</ambient><diffuse>0.72 0.74 0.76 1</diffuse></material></visual>
  </link></model>
'''


def box(name, size, pose, colour='0.55 0.6 0.65 1', mu=1.0):
    s = ' '.join(f'{v:.4f}' for v in size)
    return f'''  <model name="{name}"><static>true</static><pose>{pose}</pose><link name="link">
    <collision name="collision"><geometry><box><size>{s}</size></box></geometry><surface><friction><ode><mu>{mu}</mu><mu2>{mu}</mu2></ode></friction></surface></collision>
    <visual name="visual"><geometry><box><size>{s}</size></box></geometry><material><ambient>{colour}</ambient><diffuse>{colour}</diffuse></material></visual>
  </link></model>
'''


def flat():
    return ground()


def slope_10():
    # The robot starts on flat ground. The 10 degree ramp starts 0.5 m ahead.
    a = math.radians(10)
    length = 4.0
    c = length / 2 * math.cos(a) + 0.5
    z = length / 2 * math.sin(a) - 0.01
    return ground() + box('ramp', (length, 3.0, 0.02), f'{c:.4f} 0 {z:.4f} 0 {-a:.5f} 0')


def rough():
    # Static tiles, seeded so every run is the same. The spawn area is left flat.
    rng = random.Random(1234)
    out = [ground()]
    tile = 0.12
    n = 0
    for i in range(-25, 26):
        for j in range(-12, 13):
            x, y = i * tile, j * tile
            if abs(x) < 0.35 and abs(y) < 0.35:
                continue
            h = rng.uniform(0.002, 0.020)
            out.append(box(f't{n}', (tile, tile, h), f'{x:.3f} {y:.3f} {h / 2:.4f} 0 0 0'))
            n += 1
    return ''.join(out)


def step_2cm():
    return ground() + box('step', (3.0, 3.0, 0.02), '2.0 0 0.01 0 0 0')


def low_friction():
    return ground(mu=0.25)


WORLDS = {'flat': flat, 'slope_10': slope_10, 'rough': rough, 'step_2cm': step_2cm, 'low_friction': low_friction}


def main(directory):
    root = pathlib.Path(directory)
    root.mkdir(parents=True, exist_ok=True)
    for name, build in WORLDS.items():
        (root / f'{name}.sdf').write_text(HEADER.format(name=name) + build() + FOOTER)


if __name__ == '__main__':
    main(sys.argv[1])
